function svA(type){return S['sv_'+type]||{};}
function survey(type){
  if(S['sent_'+type])return '<div class="sv-done">✅ <b>Terima kasih'+(nm()?', '+'<span data-user-text>'+esc(nm())+'</span>':'')+'!</b> Jawapan anda telah dihantar.'+'</div>';
  var a=svA(type),h='<form class="survey" data-sv="'+type+'" novalidate>';
  if(!surveyReady())h+='<p class="tip">Jawapan disimpan dalam pelayar ini sahaja sehingga penganjur menyambungkan borang.</p>';
  if(surveyReady())h+='<div class="grid2"><div><label class="f" for="sv-'+type+'-email">Emel (untuk e-Sijil) *</label><input type="email" id="sv-'+type+'-email" name="email" value="'+esc(S.email||'')+'" placeholder="nama@contoh.com" required></div><div><label class="f" for="sv-'+type+'-name">Nama penuh *</label><input type="text" id="sv-'+type+'-name" name="fullname" value="'+esc(S.fullname||'')+'" placeholder="seperti dalam e-Sijil" required></div></div>';
  SURVEYS[type].qs.forEach(function(q,i){
    var nmq=type+'_'+q.id,lg='<legend><span class="qn">'+(i+1)+'</span>'+q.q+(q.req?' <b class="req">*</b>':'')+'</legend>'+(q.hint?'<p class="hint">'+q.hint+'</p>':'');
    if(q.t==='single'||q.t==='multi'){h+='<fieldset class="q" data-q="'+q.id+'">'+lg+'<div class="opts">'+q.o.map(function(o){var on=q.t==='single'?a[q.id]===o:(a[q.id]||[]).indexOf(o)>-1;return '<label class="opt"><input type="'+(q.t==='single'?'radio':'checkbox')+'" name="'+nmq+'" value="'+esc(o)+'"'+(on?' checked':'')+'><span>'+o+'</span></label>';}).join('')+'</div></fieldset>';}
    else if(q.t==='grid'){h+='<fieldset class="q" data-q="'+q.id+'">'+lg+'<p class="hint">1 = '+q.scale[0]+' · 5 = '+q.scale[1]+'</p>'+q.rows.map(function(r,ri){var cur=(a[q.id]||[])[ri];return '<div class="grow"><span>'+r+'</span><div class="scale" role="radiogroup" aria-label="'+esc(r)+'">'+[1,2,3,4,5].map(function(n){return '<label><input type="radio" name="'+nmq+'_'+ri+'" value="'+n+'"'+(cur==n?' checked':'')+'><span>'+n+'</span></label>';}).join('')+'</div></div>';}).join('')+'</fieldset>';}
    else if(q.t==='text'){h+='<fieldset class="q" data-q="'+q.id+'">'+lg+'<input type="text" name="'+nmq+'" value="'+esc(a[q.id]||(q.id==='pautan'?shareUrl():''))+'" placeholder="'+(q.ph||'')+'"></fieldset>';}
    else{h+='<fieldset class="q" data-q="'+q.id+'">'+lg+'<textarea name="'+nmq+'">'+esc(a[q.id]||'')+'</textarea></fieldset>';}
  });
  if(surveyReady())h+='<div class="sv-msg" role="alert"></div><div class="row"><button class="btn blue" type="submit">Hantar jawapan ✉</button></div>';
  return h+'</form>';}
function svCollect(form,type){var a={};SURVEYS[type].qs.forEach(function(q){var nmq=type+'_'+q.id;
  if(q.t==='single'){var c=form.querySelector('input[name="'+nmq+'"]:checked');a[q.id]=c?c.value:'';}
  else if(q.t==='multi'){a[q.id]=[].map.call(form.querySelectorAll('input[name="'+nmq+'"]:checked'),function(x){return x.value;});}
  else if(q.t==='grid'){a[q.id]=q.rows.map(function(_,ri){var c=form.querySelector('input[name="'+nmq+'_'+ri+'"]:checked');return c?+c.value:'';});}
  else{var el=form.querySelector('[name="'+nmq+'"]');a[q.id]=el?el.value.trim():'';}});return a;}
function svSend(payload){return fetch(SCRIPT_URL,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify(payload)}).then(function(r){return r.json();}).then(function(j){if(!j||!j.ok)throw new Error((j&&j.error)||'Gagal');return j;});}
function bindSurvey(form){var type=form.dataset.sv,msg=form.querySelector('.sv-msg');
  form.addEventListener('change',function(e){var fs=e.target.closest('.q');if(fs)fs.classList.remove('err');if(e.target.classList)e.target.classList.remove('err');S['sv_'+type]=svCollect(form,type);if(surveyReady()){S.email=form.email.value.trim();S.fullname=form.fullname.value.trim();}save();});
  form.addEventListener('input',function(e){if(e.target.type==='text'||e.target.tagName==='TEXTAREA'){S['sv_'+type]=svCollect(form,type);save();}if(e.target.name==='email'||e.target.name==='fullname'){if(surveyReady()){S.email=form.email.value.trim();S.fullname=form.fullname.value.trim();}save();}});
  form.addEventListener('submit',function(e){e.preventDefault();if(!surveyReady())return;var a=svCollect(form,type),miss=[];
    form.querySelectorAll('.q').forEach(function(f){f.classList.remove('err');});
    var email=form.email.value.trim(),full=form.fullname.value.trim();
    if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)){miss.push(form.email);form.email.classList.add('err');}else form.email.classList.remove('err');
    if(!full){miss.push(form.fullname);form.fullname.classList.add('err');}else form.fullname.classList.remove('err');
    SURVEYS[type].qs.forEach(function(q){if(!q.req)return;var bad=q.t==='grid'?a[q.id].some(function(x){return x==='';}):!a[q.id];if(bad){var f=form.querySelector('[data-q="'+q.id+'"]');f.classList.add('err');miss.push(f);}});
    if(miss.length){msg.className='sv-msg bad';msg.textContent=tr('Ada '+miss.length+' bahagian yang belum lengkap. Ruangan bertanda merah perlu diisi.');miss[0].scrollIntoView({behavior:'smooth',block:'center'});return;}
    var sessionIndex=cur;
    var btn=form.querySelector('button[type=submit]');btn.disabled=true;btn.textContent=tr('Menghantar…');msg.className='sv-msg';msg.textContent='';
    var payload={type:type,email:email.toLowerCase(),name:full,nick:nm(),lang:english?'en':'ms',answers:a,sentAt:new Date().toISOString()};
    svSend(payload).then(function(){S['sent_'+type]=true;delete S['queue_'+type];S['done'+sessionIndex]=true;save();if(!document.getElementById('workspace').hidden&&cur===sessionIndex)show(cur);})
    .catch(function(){S['queue_'+type]=payload;save();btn.disabled=false;btn.textContent=tr('Cuba hantar semula ↻');msg.className='sv-msg bad';msg.textContent=tr('Talian kurang stabil. Jawapan anda sudah disimpan dalam pelayar ini. Tekan "Cuba hantar semula" sebentar lagi.');});
  });}

