/* ===== Lapisan gerakan halaman utama ===== */
var MO={raf:0,off:0,last:0,paused:false,visible:false,drag:null};
function moCards(){
  var combos=[[0,2],[1,1],[2,0],[3,2],[1,2],[3,1],[2,1],[0,0],[3,0],[2,2],[0,1],[1,0]];
  return combos.map(function(c,i){var t=GX_TYPES[c[0]],s=GX_STYLES[c[1]];
    return '<button type="button" class="mo-card" data-mot="'+t.key+'" data-mos="'+s.key+'" aria-label="'+esc(LX(t.name)+' · '+LX(s.name))+'"><span class="mo-chip"><i class="'+s.cls+'"></i>'+LX(t.name)+' · '+LX(s.name)+'</span><span class="mo-screen mo-photo"><img src="'+gxImg(t,s,true)+'" alt="" width="800" height="450" draggable="false"></span></button>';}).join('');
}
function moRender(){
  var tr_=document.getElementById('mo-track');if(!tr_)return;
  var html=moCards();tr_.innerHTML=html+html;
  tr_.querySelectorAll('.mo-card').forEach(function(c){c.onclick=function(){if(MO.moved)return;S.type=c.dataset.mot;S.style=c.dataset.mos;S.kTab='contoh';save();go('kenali');window.scrollTo(0,0);};});
  moLayout();
}
function moReduced(){return window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches;}
function moLayout(){
  var ring=document.getElementById('mo-ring'),cards=ring?ring.querySelectorAll('.mo-card'):[];if(!cards.length)return;
  if(moReduced()){ring.classList.add('static');return;}
  var w=ring.clientWidth,cw=cards[0].offsetWidth,gap=Math.max(14,cw*.08),step=cw+gap,total=step*cards.length;
  MO.off=((MO.off%total)+total)%total;
  cards.forEach(function(c,i){
    var x=((i*step-MO.off)%total+total)%total-step; // start one card off-screen left
    if(x>total-step*1.5)x-=total;
    var center=x+cw/2-w/2,n=Math.max(-1.4,Math.min(1.4,center/(w/2)));
    var rot=n*-24,z=Math.abs(n)*Math.abs(n)*70,sc=1+Math.abs(n)*.06;
    c.style.transform='translate3d('+x+'px,0,'+z+'px) rotateY('+rot+'deg) scale('+sc+')';
    c.style.zIndex=String(100-Math.round(Math.abs(n)*50));
  });
}
function moTick(t){
  if(!MO.last)MO.last=t;var dt=Math.min(64,t-MO.last);MO.last=t;
  if(!MO.paused&&!MO.drag&&MO.visible)MO.off+=dt*.045;
  moLayout();MO.raf=MO.visible?requestAnimationFrame(moTick):0;
}
function moStart(){if(!MO.raf&&!moReduced()){MO.last=0;MO.raf=requestAnimationFrame(moTick);}}
function moInit(){
  var ring=document.getElementById('mo-ring');if(!ring)return;
  moRender();
  if('IntersectionObserver' in window){new IntersectionObserver(function(es){MO.visible=es[0].isIntersecting;if(MO.visible)moStart();}).observe(ring);}else{MO.visible=true;moStart();}
  ring.addEventListener('pointerenter',function(e){if(e.pointerType==='mouse')ring.classList.add('slow'),MO.hover=true;});
  ring.addEventListener('pointerleave',function(){MO.hover=false;ring.classList.remove('slow');});
  ring.addEventListener('pointerdown',function(e){MO.drag={x:e.clientX,o:MO.off};MO.moved=false;});
  window.addEventListener('pointermove',function(e){if(!MO.drag)return;var dx=e.clientX-MO.drag.x;if(Math.abs(dx)>6)MO.moved=true;MO.off=MO.drag.o-dx;if(!MO.raf)moLayout();});
  window.addEventListener('pointerup',function(){if(MO.drag){MO.drag=null;setTimeout(function(){MO.moved=false;},50);}});
  window.addEventListener('resize',moLayout);
  var pb=document.getElementById('mo-pause');
  if(pb)pb.onclick=function(){MO.paused=!MO.paused;pb.setAttribute('aria-pressed',MO.paused);pb.textContent=tr(MO.paused?'▶ Main':'⏸ Jeda');};
  /* chat */
  var chat=document.getElementById('chat');
  var play=function(){if(!chat)return;chat.classList.remove('play');void chat.offsetWidth;chat.classList.add('play');};
  if(chat&&'IntersectionObserver' in window){var io=new IntersectionObserver(function(es){if(es[0].isIntersecting){play();io.disconnect();}},{threshold:.35});io.observe(chat);}else play();
  var rp=document.getElementById('chat-replay');if(rp)rp.onclick=play;
  /* scroll reveal */
  var rv=document.querySelectorAll('#home .hero-card,#home .hero-media,#home .mo-head,#home .mo-ring,#home .mo-chat-copy,#home .chat,#home .landing-content>h2,#home .landing-content>.lead,#home .home-grid article,#home .guide');
  if('IntersectionObserver' in window&&!moReduced()){rv.forEach(function(el,i){el.classList.add('rv');el.style.setProperty('--rvd',(i%3)*.08+'s');});
    var ro=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('in');ro.unobserve(e.target);}});},{threshold:.12});rv.forEach(function(el){ro.observe(el);});}
  var pills=document.querySelector('.mo-pills');if(pills&&'IntersectionObserver' in window){var po=new IntersectionObserver(function(es){if(es[0].isIntersecting){pills.classList.add('drop');po.disconnect();}},{threshold:.4});po.observe(pills);}else if(pills)pills.classList.add('drop');
}

/* ===== Hero: kiraan detik dan paralaks ===== */
function hxCount(){
  var el=document.getElementById('hx-count');if(!el)return;
  var start=Date.parse('2026-11-11T09:00:00+08:00'),end=Date.parse('2026-11-11T13:00:00+08:00'),now=Date.now();
  if(now>=end){el.innerHTML='<i></i>'+tr('Bengkel telah selesai. Terima kasih kerana menyertai!');return;}
  if(now>=start){el.innerHTML='<i></i>'+tr('Sedang berlangsung sekarang');return;}
  var m=Math.floor((start-now)/60000),d=Math.floor(m/1440),h=Math.floor(m%1440/60),mi=m%60;
  el.innerHTML='<i></i>'+tr('Bermula dalam')+' <b>'+d+'</b> '+tr('hari')+' <b>'+h+'</b> '+tr('jam')+' <b>'+mi+'</b> '+tr('minit');
}
