/* ===== Halaman tambahan: Atur cara & Fasilitator ===== */
var PAGES={'atur-cara':'agenda-page','fasilitator':'about-page'};
var AG_PARTS=[
 {n:'Mula',s:'Sedia dan berkenalan',c:'blue',idx:[0,1]},
 {n:'Kenali',s:'Faham asas laman web',c:'yellow',idx:[2]},
 {n:'Bina',s:'Bina, uji dan muat turun',c:'red',idx:[3,5]},
 {n:'Terbit',s:'Dari fail ke pautan awam',c:'green',idx:[7,8]},
 {n:'Kongsi',s:'Tunjuk, tanya dan maklum balas',c:'ink',idx:[9,10,11]}
];
var AG_IC=['sparkle','clipboard','compass','pen','bot','coffee','phone','rocket','globe','message','help','heart'];
var agTimer=null;
function agMin(t){var p=t.split(':');return +p[0]*60+ +p[1];}
function agDur(i){return agMin(SES[i].e)-agMin(SES[i].t);}
function agFmt(t){var m=agMin(t),h=Math.floor(m/60),mm=m%60,hh=h>12?h-12:h;return hh+'.'+(mm<10?'0':'')+mm+' '+(h<12?'pg':'ptg');}
function agLen(m){var h=Math.floor(m/60),r=m%60;return (h?h+' '+tr('jam')+(r?' ':''):'')+(r?r+' '+tr('minit'):'');}
function agNowIndex(){var now=Date.now(),day='2026-11-11T';for(var i=0;i<SES.length;i++){if(SES[i].hide)continue;var a=Date.parse(day+SES[i].t+':00+08:00'),b=Date.parse(day+SES[i].e+':00+08:00');if(now>=a&&now<b)return i;}return -1;}
function agRender(){
  var flow=document.getElementById('ag-flow');if(!flow)return;
  var total=agMin(SES[SES.length-1].e)-agMin(SES[0].t),prak=0;SES.forEach(function(x,i){if(x.k==='prak')prak+=agDur(i);});
  var nowI=agNowIndex();
  document.getElementById('ag-stats').innerHTML=tr('<span>📅 '+agFmt(SES[0].t)+' – '+agFmt(SES[SES.length-1].e)+'</span><span>📦 '+AG_PARTS.length+' bahagian</span><span>📝 '+SES.filter(function(x){return !x.hide;}).length+' sesi</span><span>✍️ '+agLen(prak)+' praktikal</span>');
  document.getElementById('ag-bar').innerHTML=AG_PARTS.map(function(p){return p.idx.map(function(i){return '<span class="c-'+p.c+(SES[i].k==='rehat'?' brk':'')+'" style="flex:'+agDur(i)+'" title="'+esc(tr(TITLES[i]))+' · '+agDur(i)+' min"></span>';}).join('');}).join('');
  document.getElementById('ag-legend').innerHTML=AG_PARTS.map(function(p,k){var m=p.idx.reduce(function(a,i){return a+agDur(i);},0);return '<span><i class="c-'+p.c+'"></i>0'+(k+1)+' '+tr(p.n)+' <b>'+agLen(m)+'</b></span>';}).join('');
  flow.innerHTML=AG_PARTS.map(function(p,k){
    var m=p.idx.reduce(function(a,i){return a+agDur(i);},0),live=p.idx.indexOf(nowI)>=0;
    return '<li class="ag-folder c-'+p.c+(live?' live':'')+'" style="--k:'+k+'"><div class="ag-tab"><em>0'+(k+1)+'</em>'+tr(p.n)+'</div><div class="ag-body">'+'<img class="ag-ico" src="./assets/icon-'+['persediaan','kenali','praktikal','terbit','kongsi'][k]+'.png" alt="" width="64" height="64" loading="lazy">'+
      '<p class="ag-time mono2">'+agFmt(SES[p.idx[0]].t)+' – '+agFmt(SES[p.idx[p.idx.length-1]].e)+'</p><p class="ag-dur"><b>'+m+'</b> '+tr('minit')+'</p><p class="ag-sub">'+tr(p.s)+'</p>'+
      '<ul class="ag-papers">'+p.idx.map(function(i,j){return '<li style="--j:'+j+'"><a href="#'+ROUTES[i]+'" class="ag-paper'+(i===nowI?' now':'')+'"><span class="ag-pic">'+IC(AG_IC[i])+'</span><span class="ag-pt"><small>'+SES[i].t.replace(':','.')+' · '+agDur(i)+' min</small><b>'+tr(TITLES[i])+'</b><span>'+tr(SES[i].goal)+'</span></span>'+(i===nowI?'<em class="ag-live">'+tr('Sekarang')+'</em>':'')+'</a></li>';}).join('')+'</ul></div></li>';
  }).join('');
  var nw=document.getElementById('ag-now');
  if(nw)nw.innerHTML=nowI>=0?'<i></i>'+tr('Sedang berlangsung:')+' <b>'+tr(TITLES[nowI])+'</b>':'';
  var play=document.getElementById('ag-play');
  if(play)play.onclick=function(){
    var fs=flow.querySelectorAll('.ag-folder');if(agTimer){clearInterval(agTimer);agTimer=null;}
    var i=0;var step=function(){fs.forEach(function(f,k){f.classList.toggle('hot',k===i);f.classList.toggle('past',k<i);});if(window.innerWidth<=900&&fs[i])fs[i].scrollIntoView({behavior:'smooth',block:'center'});i++;if(i>fs.length){clearInterval(agTimer);agTimer=null;fs.forEach(function(f){f.classList.remove('hot','past');});}};
    step();agTimer=setInterval(step,1700);
  };
  flow.classList.remove('in');void flow.offsetWidth;
  var bar=document.getElementById('ag-bar');bar.classList.remove('in');
  [flow,bar].forEach(function(el){if('IntersectionObserver' in window){var io=new IntersectionObserver(function(es){if(es[0].isIntersecting){el.classList.add('in');io.disconnect();}},{threshold:0,rootMargin:'0px 0px -60px 0px'});io.observe(el);}else el.classList.add('in');});
}
function abInit(){
  var root=document.getElementById('about-page');if(!root||root.dataset.ready)return;root.dataset.ready='1';
  root.querySelectorAll('[data-ab]').forEach(function(b){b.onclick=function(){var k=b.dataset.ab;
    root.querySelectorAll('[data-ab]').forEach(function(x){var o=x===b;x.classList.toggle('on',o);x.setAttribute('aria-selected',o);});
    root.querySelectorAll('[data-abpane]').forEach(function(p){var o=p.dataset.abpane===k;p.hidden=!o;if(o){p.classList.remove('turn');void p.offsetWidth;p.classList.add('turn');}});};});
  var big=new Image();big.onload=function(){document.getElementById('ab-img').src=big.src;};big.src='./assets/madam-julie-large.webp';
}
function abCount(){
  document.querySelectorAll('#about-page [data-count]').forEach(function(el){var n=+el.dataset.count,t0=null;
    var f=function(t){if(!t0)t0=t;var p=Math.min(1,(t-t0)/900);el.textContent=Math.round(n*p);if(p<1)requestAnimationFrame(f);};requestAnimationFrame(f);});
}
function showPage(key){
  Object.keys(PAGES).forEach(function(k){var el=document.getElementById(PAGES[k]);if(el)el.hidden=k!==key;});
  if(key==='atur-cara')agRender();
  if(key==='fasilitator'){abInit();abCount();}
}

/* ===== Persediaan: meter kesediaan, kemajuan soal selidik, pembina ayat & dinding idea ===== */
var RD_KEYS=['a1','a2','a3','a5','a4'];
function readyMeter(){var n=RD_KEYS.filter(function(k){return S[k];}).length;
  return '<div class="rd'+(n===RD_KEYS.length?' full':'')+'" id="rd"><svg viewBox="0 0 120 120" aria-hidden="true"><circle cx="60" cy="60" r="50" class="rd-bg"/><circle cx="60" cy="60" r="50" class="rd-fg" id="rd-fg" style="stroke-dashoffset:'+(314*(1-n/RD_KEYS.length))+'"/></svg><div class="rd-txt"><b id="rd-n">'+n+'/'+RD_KEYS.length+'</b><small id="rd-l">'+tr(n===RD_KEYS.length?'Anda sudah bersedia!':'Tandakan setiap item')+'</small></div><span class="rd-burst" aria-hidden="true">'+'<i></i>'.repeat(12)+'</span></div>';}
function rdUpdate(){var n=RD_KEYS.filter(function(k){return S[k];}).length,el=document.getElementById('rd');if(!el)return;
  var was=el.classList.contains('full');document.getElementById('rd-fg').style.strokeDashoffset=314*(1-n/RD_KEYS.length);document.getElementById('rd-n').textContent=n+'/'+RD_KEYS.length;
  document.getElementById('rd-l').textContent=tr(n===RD_KEYS.length?'Anda sudah bersedia!':'Tandakan setiap item');el.classList.toggle('full',n===RD_KEYS.length);
  if(n===RD_KEYS.length&&!was){el.classList.remove('pop');void el.offsetWidth;el.classList.add('pop');}}
/* kemajuan soal selidik */
function svProg(form){var qs=form.querySelectorAll('fieldset.q'),done=0;
  qs.forEach(function(q){var ok=false,grows=q.querySelectorAll('.grow');
    if(grows.length)ok=[].every.call(grows,function(g){return g.querySelector('input:checked');});
    else if(q.querySelector('input[type=radio],input[type=checkbox]'))ok=!!q.querySelector('input:checked');
    else{var t=q.querySelector('input[type=text],textarea');ok=!!(t&&t.value.trim());}
    q.classList.toggle('done',ok);if(ok)done++;});
  var bar=form.querySelector('.sv-prog');if(!bar)return;bar.querySelector('i').style.width=(done/qs.length*100)+'%';bar.querySelector('b').textContent=done+' / '+qs.length;bar.classList.toggle('full',done===qs.length);}
/* pembina ayat */
var ICE={jenis:['laman PdP untuk kursus saya','hab pengurusan kerja unit saya','portfolio profesional saya','laman aktiviti pelajar','laman SOP dan borang jabatan'],
 siapa:['pelajar saya','rakan sekerja','peserta program','pelanggan','komuniti setempat'],
 tujuan:['mencari maklumat dengan cepat','mendaftar program dengan mudah','belajar sendiri pada bila-bila masa','melihat hasil kerja saya','menghubungi saya terus']};
function iceSentence(){var j=S.ice_jenis,s=S.ice_siapa,t=S.ice_tujuan;
  var J=j?tr(j):'[…]',W=s?tr(s):'[…]',T=t?tr(t):'[…]';
  return english?'If I could build one website today, I would build '+J+' for '+W+' so they can '+T+'.':'Kalau saya boleh bina satu laman web hari ini, saya nak bina '+J+' untuk '+W+' supaya mereka boleh '+T+'.';}
function iceBuilder(){
  var slot=function(k,lab){return '<div class="ice-slot"><p class="mono2">'+lab+'</p><div class="ice-chips">'+ICE[k].map(function(o){var on=S['ice_'+k]===o;return '<button type="button" class="ice-chip'+(on?' on':'')+'" data-ice="'+k+'" data-v="'+esc(o)+'" aria-pressed="'+on+'">'+o+'</button>';}).join('')+'</div></div>';};
  return '<div class="ice"><div class="ice-build">'+slot('jenis','1 · Saya nak bina')+slot('siapa','2 · Untuk')+slot('tujuan','3 · Supaya mereka boleh')+
   '<div class="row"><button type="button" class="btn sm" id="ice-rand">🎲 Cuba idea rawak</button></div></div>'+
   '<div class="ice-out"><div class="ice-bubble"><span class="ice-av" data-user-text>'+esc((nm()||'A').charAt(0).toUpperCase())+'</span><p id="ice-prev" data-user-text>'+esc(S.ice||iceSentence())+'</p></div>'+
   '<label class="f" for="f-ice">Ubah ayat anda jika perlu</label><textarea id="f-ice" data-k="ice">'+esc(S.ice||iceSentence())+'</textarea>'+
   '<div class="row"><button class="btn sm" type="button" data-copy="f-ice">Salin untuk chat Meet</button><button class="btn blue sm" type="button" id="ice-pin">📌 Tampal di Dinding Idea</button></div><p class="hint" id="ice-msg" aria-live="polite"></p></div></div>'+
   '<h2>3 · Dinding Idea</h2><p>Idea rakan sebengkel muncul di sini secara langsung.</p><div class="wall" id="wall" aria-live="polite"></div>';
}
var WALL_SAMPLE=[['Contoh idea','Laman nota Bahasa Inggeris untuk pelajar semester 1'],['Contoh idea','Laman program Hari Inovasi unit saya'],['Contoh idea','Portfolio projek akhir pelajar kejuruteraan'],['Contoh idea','Laman tempahan kek untuk perniagaan keluarga']];
var wallTimer=null,wallMine=[];
function wallRender(list){var w=document.getElementById('wall');if(!w)return wallStop();
  var html=list.map(function(x,i){return '<div class="wb c'+(i%5)+(x.mine?' mine':'')+(x.demo?' demo':'')+'" style="--i:'+i+';--r:'+((i*37%9)-4)+'deg"><b>'+esc(x.n)+''+'</b><span>'+esc(x.t)+'</span></div>';}).join('');
  if(w.dataset.h!==html){w.innerHTML=html;w.dataset.h=html;}}
function wallLoad(){
  if(!document.getElementById('wall'))return wallStop();
  var mine=wallMine.map(function(t){return {n:nm()||tr('Idea saya'),t:t,mine:true};});
  if(!surveyReady()){wallRender(mine.concat(WALL_SAMPLE.map(function(x){return {n:tr(x[0]),t:tr(x[1]),demo:true};})));return;}
  fetch(SCRIPT_URL+'?type=ideas&t='+Date.now()).then(function(r){return r.json();}).then(function(j){
    var ideas=(j&&j.ideas)||[];var seen={};ideas.forEach(function(x){seen[x.t]=1;});
    wallRender(mine.filter(function(x){return !seen[x.t];}).concat(ideas.length?ideas:WALL_SAMPLE.map(function(x){return {n:tr(x[0]),t:tr(x[1]),demo:true};})));
  }).catch(function(){wallRender(mine);});
}
function wallStop(){if(wallTimer){clearInterval(wallTimer);wallTimer=null;}}
function bindPrep(){
  if(document.getElementById('rd'))document.querySelectorAll('#panel input[type=checkbox][data-k]').forEach(function(c){c.addEventListener('change',function(){setTimeout(rdUpdate,0);});});
  document.querySelectorAll('#panel form.survey').forEach(function(f){var head=document.createElement('div');head.className='sv-prog';head.innerHTML='<span class="mono2">'+tr('Kemajuan')+'</span><div><i></i></div><b>0</b>';f.insertBefore(head,f.firstChild);
    f.addEventListener('change',function(){svProg(f);});f.addEventListener('input',function(){svProg(f);});svProg(f);});
  var root=document.querySelector('#panel .ice');if(!root){wallStop();return;}
  var setSentence=function(type){var s=iceSentence(),ta=document.getElementById('f-ice'),pv=document.getElementById('ice-prev');S.ice=s;save();ta.value=s;
    if(!type){pv.textContent=s;return;}pv.textContent='';var i=0;var tick=function(){pv.textContent=s.slice(0,i+=3);if(i<s.length)requestAnimationFrame(tick);};tick();};
  root.querySelectorAll('[data-ice]').forEach(function(b){b.onclick=function(){var k=b.dataset.ice;S['ice_'+k]=b.dataset.v;
    root.querySelectorAll('[data-ice="'+k+'"]').forEach(function(x){var o=x===b;x.classList.toggle('on',o);x.setAttribute('aria-pressed',o);});setSentence(true);};});
  document.getElementById('f-ice').addEventListener('input',function(e){document.getElementById('ice-prev').textContent=e.target.value;});
  document.getElementById('ice-rand').onclick=function(){var keys=['jenis','siapa','tujuan'],n=0;root.classList.add('spin');
    var spin=setInterval(function(){keys.forEach(function(k){var o=ICE[k][Math.floor(Math.random()*ICE[k].length)];S['ice_'+k]=o;
      root.querySelectorAll('[data-ice="'+k+'"]').forEach(function(x){var on=x.dataset.v===o;x.classList.toggle('on',on);x.setAttribute('aria-pressed',on);});});
      if(++n>7){clearInterval(spin);root.classList.remove('spin');setSentence(true);}},90);};
  document.getElementById('ice-pin').onclick=function(){var t=document.getElementById('f-ice').value.trim(),msg=document.getElementById('ice-msg'),btn=this;
    if(t.length<8||t.indexOf('[…]')>-1){msg.textContent=tr('Lengkapkan ayat anda dahulu.');return;}
    if(wallMine.indexOf(t)<0)wallMine.unshift(t);wallLoad();
    if(!surveyReady()){msg.textContent=tr('Idea anda dipaparkan di dinding pada skrin ini. Kongsi juga dalam chat Meet.');return;}
    btn.disabled=true;msg.textContent=tr('Menghantar…');
    svSend({type:'idea',nick:nm()||'',idea:t,lang:english?'en':'ms'}).then(function(){msg.textContent=tr('Idea anda sudah ditampal. Terima kasih!');wallLoad();})
      .catch(function(){msg.textContent=tr('Tidak dapat menghantar. Kongsi idea anda dalam chat Meet.');}).then(function(){btn.disabled=false;});};
  wallStop();wallLoad();wallTimer=setInterval(wallLoad,15000);
}

