function rtStop(){if(rtTimer){clearInterval(rtTimer);rtTimer=null;}}
function bindRest(){var r=document.getElementById('rt');if(!r){rtStop();return;}var end=null,total=600;
  var draw=function(left){var m=Math.floor(left/60),s=left%60;document.getElementById('rt-t').textContent=m+':'+(s<10?'0':'')+s;document.getElementById('rt-fg').style.strokeDashoffset=553*(1-left/total);};
  var tick=function(){if(!document.getElementById('rt'))return rtStop();var left=Math.max(0,Math.round((end-Date.now())/1000));draw(left);document.getElementById('rt-cue').textContent=tr(Math.floor(Date.now()/4000)%2?'Hembus perlahan…':'Tarik nafas…');
    if(left===0){rtStop();r.classList.remove('run');r.classList.add('end');document.getElementById('rt-s').textContent=tr('Masa untuk sambung!');}};
  var now=new Date(),day='2026-11-11T',a=Date.parse(day+'10:35:00+08:00'),b=Date.parse(day+'10:45:00+08:00');
  var start=function(ms){rtStop();end=Date.now()+ms;r.classList.add('run');r.classList.remove('end');document.getElementById('rt-s').textContent=tr('Rehat 10 minit');tick();rtTimer=setInterval(tick,1000);};
  document.getElementById('rt-go').onclick=function(){start(total*1000);};
  document.getElementById('rt-reset').onclick=function(){rtStop();r.classList.remove('run','end');draw(total);};
  draw(total);if(Date.now()>=a&&Date.now()<b){end=b;r.classList.add('run');tick();rtTimer=setInterval(tick,1000);}
}
/* penguji peranti */
function dvBlock(){var d=S.dv||'desk';return '<h2>'+tr('Uji laman anda pada tiga saiz skrin')+'</h2><p>'+tr('Pilih fail index.html anda untuk melihatnya di sini. Fail anda kekal dalam komputer anda dan tidak dimuat naik ke mana-mana.')+'</p>'+
  '<div class="ax-tools"><label class="btn blue sm dv-file">'+IC('package')+' '+tr('Pilih laman-saya.zip')+'<input type="file" accept=".zip,.html,.htm" id="dv-in" hidden></label><label class="btn sm dv-file">'+IC('folder')+' '+tr('Pilih folder')+'<input type="file" id="dv-dir" webkitdirectory multiple hidden></label><div class="ax-seg" role="group" aria-label="'+esc(tr('Saiz skrin'))+'">'+[['desk','monitor','Desktop'],['tab','layout','Tablet'],['mob','phone','Telefon']].map(function(x){return '<button type="button" class="'+(d===x[0]?'on':'')+'" data-dv="'+x[0]+'" aria-pressed="'+(d===x[0])+'">'+IC(x[1])+' '+tr(x[2])+'</button>';}).join('')+'</div><small class="hint" id="dv-name">'+tr('Belum ada fail. Pratonton rangka dipaparkan.')+'</small></div>'+
  '<div class="dv dv-'+d+'" id="dv"><div class="dv-frame"><div class="wf-bar"><span></span><span></span><span></span></div><div class="dv-screen" id="dv-screen">'+bpSite()+'</div></div></div>';}
function bindDevice(){var dv=document.getElementById('dv');if(!dv)return;
  document.querySelectorAll('#panel [data-dv]').forEach(function(b){b.onclick=function(){S.dv=b.dataset.dv;save();dv.className='dv dv-'+S.dv;document.querySelectorAll('#panel [data-dv]').forEach(function(x){var o=x===b;x.classList.toggle('on',o);x.setAttribute('aria-pressed',o);});};});
  var show=function(html,name){var fr=document.createElement('iframe');fr.setAttribute('sandbox','allow-scripts');fr.setAttribute('title',tr('Pratonton laman anda'));fr.srcdoc=html;var sc=document.getElementById('dv-screen');sc.innerHTML='';sc.appendChild(fr);sc.classList.add('live');document.getElementById('dv-name').textContent='✓ '+name;};
  var fail=function(){document.getElementById('dv-name').textContent=tr('Tiada index.html dijumpai. Pastikan index.html berada di dalam folder laman-saya.');};
  var inp=document.getElementById('dv-in');if(inp)inp.onchange=function(){var f=inp.files&&inp.files[0];if(!f)return;
    if(/\.zip$/i.test(f.name)){if(!zipReady()){fail();return;}JSZip.loadAsync(f).then(function(z){var map={},jobs=[];z.forEach(function(path,e){if(!e.dir&&!/__MACOSX|\.DS_Store/.test(path))jobs.push(e.async('blob').then(function(b){var t=/\.html?$/i.test(path)?'text/html':/\.css$/i.test(path)?'text/css':/\.svg$/i.test(path)?'image/svg+xml':/\.js$/i.test(path)?'text/javascript':'';map[path]=t?new Blob([b],{type:t}):b;}));});return Promise.all(jobs).then(function(){return siteFromFiles(map);});}).then(function(u){show(u,f.name);}).catch(fail);}
    else{var rd=new FileReader();rd.onload=function(){show(String(rd.result),f.name);};rd.readAsText(f);}};
  var dir=document.getElementById('dv-dir');if(dir)dir.onchange=function(){var map={};[].forEach.call(dir.files,function(f){map[f.webkitRelativePath||f.name]=f;});siteFromFiles(map).then(function(u){show(u,(dir.files[0]&&dir.files[0].webkitRelativePath||'').split('/')[0]||tr('Folder'));}).catch(fail);};}
function bindPrac(){
  var form=document.querySelector('#panel .bp-wrap');
  if(form){var tmr=null;form.querySelectorAll('[data-k]').forEach(function(el){var k=el.dataset.k;
    el.addEventListener('input',function(){clearTimeout(tmr);tmr=setTimeout(function(){bpRefresh(k);},120);});
    el.addEventListener('focus',function(){var p=document.getElementById('bp-prev');if(p){p.querySelectorAll('.bp-focus').forEach(function(x){x.classList.remove('bp-focus');});var t=p.querySelector(BP_PART[k]||'');if(t)t.classList.add('bp-focus');}});
    el.addEventListener('blur',function(){var p=document.getElementById('bp-prev');if(p)p.querySelectorAll('.bp-focus').forEach(function(x){x.classList.remove('bp-focus');});});});}
  document.querySelectorAll('#panel [data-bf]').forEach(function(b){b.onclick=function(){var i=+b.dataset.bf;S['bf'+i]=!S['bf'+i];save();bfUpdate();};});
  var cp=document.querySelector('#panel [data-copy="pr-main"]');if(cp)cp.addEventListener('click',function(){if(!S.bf0){S.bf0=true;save();bfUpdate();}});
  var pl=document.getElementById('bf-play');if(pl)pl.onclick=bfDemo;
  bindRest();bindDevice();
}

/* ===== Penerbitan: pemilih platform, simulator langkah, Netlify Drop, sambutan URL ===== */
function pubFlow(){return '<div class="pf-run" id="pf-run" aria-hidden="true"><div class="pf-path"><i class="pf-rocket">'+IC('rocket')+'</i></div>'+
  [['folder','Folder projek'],['server','Hos'],['link','Pautan awam'],['globe','Seluruh dunia']].map(function(x,i){return '<span class="pf-stop" style="--i:'+i+'">'+IC(x[0])+'<b>'+tr(x[1])+'</b></span>';}).join('')+'</div>';}
var PQ=[['Adakah anda mahu mengemas kini laman ini dari semasa ke semasa?',['Ya, kerap','Jarang']],['Adakah anda sudah ada akaun GitHub?',['Ya','Belum']],['Apa yang paling penting untuk anda hari ini?',['Belajar cara yang kekal','Terbit dengan paling cepat']]];
function pubPicker(){var a=S.pq||[];return '<h2>'+tr('Platform mana sesuai untuk anda?')+'</h2><p>'+tr('Jawab tiga soalan pantas. Kami cadangkan laluan yang paling sesuai.')+'</p><div class="pq" id="pq">'+
  PQ.map(function(q,i){return '<div class="pq-q'+(i<=a.length?' open':'')+'" style="--i:'+i+'"><p><em>'+(i+1)+'</em>'+tr(q[0])+'</p><div class="pq-opts">'+q[1].map(function(o,j){var on=a[i]===j;return '<button type="button" class="dk-opt'+(on?' on':'')+'" data-pq="'+i+'" data-v="'+j+'" aria-pressed="'+on+'"><em>'+'AB'[j]+'</em>'+tr(o)+'</button>';}).join('')+'</div></div>';}).join('')+
  '<div class="pq-res" id="pq-res">'+pubResult()+'</div></div>';}
function pubResult(){var a=S.pq||[];if(a.length<3)return '';var gh=(a[0]===0?1:0)+(a[1]===0?1:0)+(a[2]===0?1:0);var g=gh>=2;
  return '<div class="pq-card '+(g?'gh':'nl')+'"><span class="pq-ic">'+IC(g?'folder':'rocket')+'</span><div><p class="mono2">'+tr('Cadangan kami')+'</p><h3>'+(g?'GitHub Pages':'Netlify Drop')+'</h3><p>'+tr(g?'Sesuai jika anda mahu menyimpan fail dengan teratur dan mengemas kini laman selepas bengkel.':'Sesuai jika anda mahu laman live dalam beberapa minit dengan seret dan lepas folder.')+'</p><a class="btn blue sm" href="#'+(g?'github':'netlify')+'">'+tr('Buka panduan')+' →</a> <a class="btn sm" href="#'+(g?'netlify':'github')+'">'+tr('Lihat pilihan lain')+'</a></div></div>';}
/* simulator */
