var REFS=kRefsLoad(); // gambar rujukan: dikongsi dengan Studio melalui ww-refs-v1 (kekal dalam pelayar ini sahaja)
/* v43: satu rekod projek dikongsi Kenali ↔ Studio */
function kGet(k,d){try{var o=JSON.parse(localStorage.getItem(k)||'null');return o==null?d:o;}catch(e){return d;}}
function kSet(k,o){try{localStorage.setItem(k,JSON.stringify(o));return true;}catch(e){return false;}}
function kRefsLoad(){var L=kGet('ww-refs-v1',[]);return Array.isArray(L)?L.filter(function(r){return r&&(r.d||r.src);}).slice(0,4).map(function(r){return {url:r.d||r.src,src:r.src||'',pal:r.pal||[]};}):[];}
function kRefsSave(){kSet('ww-refs-v1',REFS.map(function(r){return r.src?{src:r.src,pal:r.pal}:{d:r.url,pal:r.pal};}));if(typeof wwSendKenali==='function')wwSendKenali();}
function kShrink(file,max,png,cb){var rd=new FileReader();rd.onload=function(){var img=new Image();img.onload=function(){var k=Math.min(1,max/Math.max(img.naturalWidth,img.naturalHeight)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.naturalWidth*k));c.height=Math.max(1,Math.round(img.naturalHeight*k));var x=c.getContext('2d');if(!png){x.fillStyle='#fff';x.fillRect(0,0,c.width,c.height);}x.drawImage(img,0,0,c.width,c.height);cb(c.toDataURL(png?'image/png':'image/jpeg',.84),img);};img.onerror=function(){cb(null);};img.src=rd.result;};rd.readAsDataURL(file);}
/* gambar hero & logo dari perancang aset turut dihantar ke Studio (masuk ke dalam ZIP Studio) */
function kMirrorAsset(name,file){var key=name==='hero.png'?'hero':name==='logo.png'?'logo':'';if(!key)return;kShrink(file,key==='hero'?1600:512,key==='logo',function(d){if(!d)return;var o=kGet('ww-img-v1',{});o[key]={d:d,n:key==='hero'?'hero.jpg':'logo.png'};kSet('ww-img-v1',o);if(typeof wwSendKenali==='function')wwSendKenali();});}
