function refPalette(img){try{var c=document.createElement('canvas'),w=64,h=Math.max(1,Math.round(64*img.naturalHeight/img.naturalWidth));c.width=w;c.height=h;var x=c.getContext('2d');x.drawImage(img,0,0,w,h);var d=x.getImageData(0,0,w,h).data,b={};
  for(var i=0;i<d.length;i+=4){if(d[i+3]<128)continue;var k=(d[i]>>4)+','+(d[i+1]>>4)+','+(d[i+2]>>4);b[k]=(b[k]||0)+1;}
  var hex=function(k){return '#'+k.split(',').map(function(n){var v=(+n<<4)+8;return ('0'+v.toString(16)).slice(-2);}).join('');};
  var dist=function(a,b){var p=a.split(',').map(Number),q=b.split(',').map(Number);return Math.abs(p[0]-q[0])+Math.abs(p[1]-q[1])+Math.abs(p[2]-q[2]);};
  var out=[];Object.keys(b).sort(function(p,q){return b[q]-b[p];}).forEach(function(k){if(out.length<6&&out.every(function(o){return dist(o,k)>4;}))out.push(k);});return out.map(hex);}catch(e){return [];}}
